#include <cmath>

extern "C" double mms_source_dens(double x, double y) {
    return (-0.024999999999999998*x*sin(2*x - 2*y) + 0.024999999999999998*x*sin(2*x + 2*y) - 0.19999999999999998*x*cos(x - y) + 0.19999999999999998*x*cos(x + y) + 0.10000000000000001*sin(x - y) + 0.5*sin(x + y) + 0.074999999999999997*cos(2*y) - 0.25*cos(x - y) + 0.25*cos(x + y) - 0.025000000000000001*cos(2*x - 2*y) - 0.049999999999999996*cos(2*x + 2*y))/x;
}

extern "C" double mms_source_mom1(double x, double y) {
    return (-0.040000000000000001*x*sin(2*x) - 0.20000000000000001*x*sin(x - y) - 0.20000000000000001*x*sin(x + y) + 0.02*x*sin(2*x - 2*y) + 0.02*x*sin(2*x + 2*y) - 0.00062500000000000012*x*cos(x - 3*y) + 0.00062500000000000012*x*cos(x - y) + 0.00062500000000000012*x*cos(x + y) - 0.00062500000000000012*x*cos(x + 3*y) - 0.0018749999999999999*x*cos(3*x - 3*y) + 0.0018749999999999999*x*cos(3*x - y) + 0.0018749999999999999*x*cos(3*x + y) - 0.0018749999999999999*x*cos(3*x + 3*y) - 0.074999999999999997*sin(2*y) + 0.00078125000000000026*sin(x - 3*y) - 0.25265625000000003*sin(x - y) - 0.25453124999999999*sin(x + y) + 0.0064062500000000005*sin(x + 3*y) - 0.012499999999999997*sin(2*x - 2*y) + 0.0625*sin(2*x + 2*y) + 0.00078124999999999983*sin(3*x - 3*y) + 0.0010937499999999992*sin(3*x - y) + 0.0029687500000000009*sin(3*x + y) - 0.00484375*sin(3*x + 3*y) + 0.065000000000000002*cos(2*x) + 0.025000000000000001*cos(2*y) - 0.39999999999999997*cos(x - y) + 0.80000000000000004*cos(x + y) - 0.0025000000000000022*cos(2*x - 2*y) - 0.0625*cos(2*x + 2*y) - 2.0249999999999999)/x;
}

extern "C" double mms_source_mom2(double x, double y) {
    return (-0.5*pow(0.29999999999999999*sin(x)*sin(y) + 1.0, 2)*sin(x)*sin(y) + 0.59999999999999998*(0.29999999999999999*sin(x)*sin(y) + 1.0)*(0.5*sin(x)*cos(y) + 2.0)*sin(x)*cos(y) + (-0.20000000000000001*x*(0.29999999999999999*sin(x)*sin(y) + 1.0)*(0.5*sin(x)*cos(y) + 2.0)*sin(x) + 0.10000000000000001*x*(0.29999999999999999*sin(x)*sin(y) + 1.0)*pow(cos(x), 2)*cos(y) + x*(0.029999999999999999*sin(x)*cos(y) + 0.12)*sin(y)*pow(cos(x), 2) + 0.40000000000000002*(0.29999999999999999*sin(x)*sin(y) + 1.0)*(0.5*sin(x)*cos(y) + 2.0)*cos(x))*sin(y) - 0.40000000000000002*sin(y)*cos(x))/x;
}

extern "C" double mms_source_etot(double x, double y) {
    return (1.0/2.0)*(-0.20000000000000001*x*((0.5*sin(x)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(x), 2)) + 2.0*cos(x)*cos(y) + 14.999999999999998)*sin(x)*sin(y) + 0.20000000000000001*x*((0.099999999999999978*sin(x)*sin(y) + 0.59999999999999998)*(0.5*sin(x)*cos(y) + 2.0)*sin(y)*cos(x) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(x), 2))*cos(x)*cos(y) - 2.0*sin(x)*cos(y))*sin(y)*cos(x) - (0.29999999999999999*sin(x)*sin(y) + 1.0)*(-(0.5*sin(x)*cos(y) + 2.0)*(0.099999999999999992*pow(sin(x), 2)*sin(y) + 0.59999999999999998*sin(x) + 0.080000000000000002*sin(y))*cos(y) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(x), 2))*sin(x)*sin(y) + 2.0*sin(y)*cos(x)) + 0.29999999999999999*((0.5*sin(x)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(x), 2)) + 2.0*cos(x)*cos(y) + 14.999999999999998)*sin(x)*cos(y) + 0.20000000000000001*((0.5*sin(x)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y) + 1.0, 2) + 0.040000000000000008*pow(sin(y), 2)*pow(cos(x), 2)) + 2.0*cos(x)*cos(y) + 14.999999999999998)*sin(y)*cos(x))/x;
}
